<template>  <div class="app-container">    <el-row>      <publish primary-key="matchCfgId" key-id="ItemConfig" :env-empty="true" :attr-names="AttrNames" :head-attrs="['matchCfgId','title']" />    </el-row>    <el-row>      <div style="float: right; margin-bottom: 10px;">        <el-button size="mini" icon="el-icon-plus" @click="showForm()">添加道具</el-button>      </div>      <el-table        :data="tableData"        stripe        :header-cell-style="libShow.DefaultTableHeadClass"        :cell-style="libShow.TableCell(10)"        style="width: 100%"      >        <el-table-column          prop="ID"          label="道具ID"          sortable          width="100"        />        <el-table-column          prop="item_name"          label="道具名称"          show-overflow-tooltip        />        <el-table-column          prop="image"          label="ICON"        />        <el-table-column          prop="item_cost"          label="道具价值"        />        <el-table-column          prop="expire_time"          label="过期时间"        >          <template slot-scope="scope">            {{ formatTime(scope.row.expire_time) }}          </template>        </el-table-column>        <el-table-column          prop="create_time"          label="创建时间"        >          <template slot-scope="scope">            {{ formatTime(scope.row.create_time) }}          </template>        </el-table-column>        <el-table-column          prop="modifier"          label="操作人"        />      </el-table>    </el-row>    <el-row type="flex" justify="center">      <div class="block">        <el-pagination          :current-page="page"          :page-sizes="[10, 20, 30, 40]"          :page-size="limit"          layout="slot, total, sizes, prev, next"          prev-text="上一页"          next-text="下一页"          :total="total"          @size-change="handleSizeChange"          @current-change="handleCurrentChange"        >          <span class="pageSizeInput" style="padding-right: 10px">            当前页：{{ page }}/{{ Math.ceil(total/limit) }}          </span>        </el-pagination>      </div>    </el-row>    <el-dialog      :title="editForm.title"      :visible.sync="editForm.visable"      :close-on-click-modal="false"      :close-on-press-escape="false"      width="900px"    >      <el-form :model="editForm.data" label-width="200px" size="mini">        <fieldset>          <legend>道具信息</legend>          <el-form-item label="道具名称：" :required="true">            <el-input v-model="editForm.data.itemName" style="width: 150px;" placeholder="请填写道具名称" />          </el-form-item>          <el-form-item label="道具价值：" :required="true">            <el-input v-model="editForm.data.itemCost" style="width: 150px;" placeholder="请填写道具价值" />          </el-form-item>          <el-form-item label="道具类别：" :required="true">            <el-select v-model="editForm.data.itemType" style="width: 150px;" placeholder="请选择道具分类">              <el-option                v-for="item in itemTypeCfgs"                :key="item.value"                :label="item.label"                :value="item.value"                :disabled="item.disabled"              />            </el-select>          </el-form-item>          <el-form-item label="道具描述：" :required="true">            <el-input v-model="editForm.data.describe" style="width: 150px;" placeholder="请填写道具描述" />          </el-form-item>          <el-form-item label="道具过期时间：" :required="true">            <el-date-picker              v-model="editForm.itemEndDate"              size="mini"              type="date"              placeholder="选择过期日期"            />            <span style="color:black; margin-left:10px">[00:00:00]</span>          </el-form-item>          <el-form-item label="道具ICON：" :required="true">            <ImagePicker v-model="editForm.data.image" />          </el-form-item>        </fieldset>        <el-form-item>          <el-button size="medium" type="primary" icon="el-icon-s-order" @click="saveItemConfig()">保存道具配置</el-button>        </el-form-item>      </el-form>    </el-dialog>  </div></template><script>import store from '@/store'import { Message } from 'element-ui'import Compare from '@/components/Compare'import Publish from '@/components/Publish'import request from '@/utils/request'import DateTimeShow from '@/components/DatetimeShow'import { $libDate, $libShow } from '@/utils/common'import ImagePicker from '@/components/ImagePicker/ImagePicker.vue'export default {  name: 'itemConfig',  components: { Compare, Publish, DateTimeShow, ImagePicker },  data() {    return {      libShow: $libShow,      pickerOptions: $libShow.DefaultDatePickerOptions(),      selectTime: [$libDate.GetDayBegin(new Date().setSeconds(0)), $libDate.GetDayEnd(new Date().setSeconds(0))],      imagePickerVisible: false,      appidInfoCfgs: [        { 'value': 1000002, 'label': 'dayusenlin' },        { 'value': 1000003, 'label': 'testaccount' },        { 'value': 1000004, 'label': 'testkey' },        { 'value': 1000005, 'label': 'BingoPlusTongits' },        { 'value': 1000006, 'label': 'BingoPlusTest' },        { 'value': 1000007, 'label': 'br' },        { 'value': 1000008, 'label': 'gli' },        { 'value': 1100000, 'label': 'xworld' }      ],      channelIdCfgs: [        { 'value': 'BP', 'label': 'BP' },        { 'value': 'AP', 'label': 'AP' },        { 'value': 'GP', 'label': 'GP' },        { 'value': 'TP', 'label': 'TP' },        { 'value': 'PG', 'label': 'PG' },        { 'value': 'Dev', 'label': 'Dev' }      ],      itemTypeCfgs: [        { 'value': 100, 'label': 'Tongits门票', disabled: false },        { 'value': 101, 'label': 'Tongits话费券',disabled: false }      ],      tableData: [],      limit: 10,      total: 0,      page: 1,      editForm: {        visable: false,        title: '',        isAdd: false,        data:{          ID:0,          itemName: '',          itemCost: 0,          itemType: 0,          describe: '',          expireTime: '',          image: ''        },        itemEndDate: $libDate.GetDayBegin(new Date().setSeconds(0))      },      AttrNames: {        itemName: '道具名称',        itemCost: '道具价值',        itemType: '道具分类',        describe: '道具描述',        image: 'ICON链接',        expireTime: '过期时间'      }    }  },  created(){    this.name = store.getters.name    this.env = store.getters.env || this.env  },  mounted(){    this.getList()  },  methods: {    getList() {      request({        url: '/itemconfig/item/config/list',        method: 'get',        data: {          Env: this.env,          PageNum: this.page,          PageSize: this.limit        }      }).then(response => {        if (response.RetCode === 0) {          const objs = response.Data || {}          if (objs.total > 0) {            this.tableData = []            this.tableData = objs.list          }        }      })    },    handleSizeChange(val) {      this.limit = val      this.getList()    },    handleCurrentChange(val) {      this.page = val      this.getList()    },    formatNum(n) {      return n.toLocaleString()    },    formatTime(ts) {      return $libDate.FormateSecondStr(ts, 2)    },    showForm() {      this.editForm.title = "新增道具配置"      this.editForm.data = {        ID: 0,        itemName: '',        itemCost: '',        itemType: '',        describe: '',        image: '',        expireTime: ''      }      this.editForm.itemEndDate = $libDate.GetDayBegin(new Date().setSeconds(0))      this.editForm.visable = true      this.editForm.isAdd = true    },    saveItemConfig() {      if (!this.configCheck()) {        return      }      let expireTime = 0      expireTime =  (Math.floor(this.editForm.itemEndDate / 1000))      request({        url: '/itemconfig/item/config/create',        method: 'POST',        data: {          Env: this.env,          Id: this.editForm.data.ID,          ItemName: this.editForm.data.itemName,          ItemCost: this.editForm.data.itemCost,          ItemType: this.editForm.data.itemType,          Describe: this.editForm.data.describe,          Image: this.editForm.data.image,          ExpireTime: expireTime        }      }).then(response => {        if (response.RetCode === 0) {          let showMsg = '新增道具配置成功！'          Message.success(showMsg)          this.getList()          this.editForm.visable = false        } else {          let errMsg = '新增道具配置失败！'          Message.error(errMsg + response.Data)        }      })    },    errmsg(txt) {      this.$alert(txt, '', {        type: 'error',        center: true,        showConfirmButton: false      })    },    timeToSec(time) {      var s = ''      var hour = time.split(':')[0]      var min = time.split(':')[1]      var sec = time.split(':')[2]      s = Number(hour * 3600) + Number(min * 60) + Number(sec)      return s    },    configCheck() {      return true    }  }}</script>